package com.oms.order.service;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import com.alibaba.druid.pool.DruidDataSource;
import javax.annotation.Resource;
import java.sql.*;
import java.util.*;
import static com.oms.order.service.OrderValues.*;

/** Company-scoped configuration. Public queries never select the password ciphertext. */
@Service
public class PushSourceService {
    @Resource private OrderRepository repository;
    @Resource private PushSourceSecrets secrets;
    public List<Map<String,Object>> list(String company){return repository.db().query("SELECT s.source_key,s.source_name,s.host,s.port,s.database_name,s.username,s.enabled,s.revision,s.last_test_status,s.last_test_time,s.last_test_message,s.update_time,(SELECT COUNT(*) FROM oms_order_pull_config c WHERE c.company_code=s.company_code AND c.source_key=s.source_key) bound_shops FROM oms_order_push_source s WHERE s.company_code=? ORDER BY s.create_time,s.source_key",ROW,company);}
    public List<Map<String,Object>> choices(String company){return repository.db().query("SELECT source_key AS `key`,source_name AS label,enabled FROM oms_order_push_source WHERE company_code=? ORDER BY source_name",ROW,company);}
    private Map<String,Object> row(String company,String key){List<Map<String,Object>> found=repository.db().query("SELECT * FROM oms_order_push_source WHERE company_code=? AND source_key=?",ROW,company,key);require(found.size()==1,"推送库不存在或不属于当前公司");return found.get(0);}
    public boolean configured(String company,String key){return repository.db().queryForObject("SELECT COUNT(*) FROM oms_order_push_source WHERE company_code=? AND source_key=? AND enabled=1",Long.class,company,key)==1;}
    public TmallPushReader.Source resolve(String company,String key){Map<String,Object> row=row(company,key);require(number(row,"enabled")==1,"推送库已停用，请在拉单管理中检查配置");return connection(company,row,secrets.decrypt(company,text(row,"password_cipher")));}
    private TmallPushReader.Source connection(String company,Map<String,Object> input,String password){TmallPushReader.Source s=new TmallPushReader.Source();s.setJdbcUrl("jdbc:mysql://"+text(input,"host")+":"+number(input,"port")+"/"+text(input,"database_name")+"?useSSL=false&serverTimezone=Asia/Shanghai&connectTimeout=5000&socketTimeout=15000");s.setUsername(text(input,"username"));s.setPassword(password);s.setRevision(number(input,"revision"));return s;}
    private Map<String,Object> validate(String company,Map<String,Object> input){Map<String,Object> value=new LinkedHashMap<>(input);String name=text(value,"source_name").trim(),host=text(value,"host").trim(),database=text(value,"database_name").trim(),username=text(value,"username").trim();require(!name.isEmpty()&&name.length()<=100,"请填写推送库名称");require(host.matches("[A-Za-z0-9][A-Za-z0-9.-]{0,252}"),"请填写有效数据库IP或主机名");require(database.matches("[A-Za-z0-9_]{1,64}"),"数据库名称无效");require(!username.isEmpty()&&username.length()<=64,"请填写数据库账号");require(number(value,"port")>0&&number(value,"port")<=65535,"数据库端口无效");require(number(value,"enabled")==0||number(value,"enabled")==1,"启用状态无效");value.put("source_name",name);value.put("host",host);value.put("database_name",database);value.put("username",username);String password=text(value,"password");if(password.isEmpty()){require(!text(value,"source_key").isEmpty(),"新增推送库请填写密码");password=secrets.decrypt(company,text(row(company,text(value,"source_key")),"password_cipher"));}require(password.length()<=1000,"数据库密码过长");value.put("password",password);return value;}
    private void probe(TmallPushReader.Source source){try(DruidDataSource pool=TmallPushReader.createPool(source);Connection connection=pool.getConnection()){
        connection.setReadOnly(true);connection.setAutoCommit(false);
        try(PreparedStatement statement=connection.prepareStatement("SELECT tid,status,type,seller_nick,created,modified,jdp_modified,jdp_response FROM jdp_tb_trade WHERE seller_nick=? LIMIT 1")){statement.setString(1,"__OMS_CONNECTIVITY_CHECK_NO_SHOP__");statement.setQueryTimeout(12);try(ResultSet ignored=statement.executeQuery()){}connection.rollback();}
    }catch(Exception e){throw new IllegalArgumentException("连接测试失败，请检查地址、账号权限和jdp_tb_trade表结构");}}
    public void test(String company,Map<String,Object> input){Map<String,Object> value=validate(company,input);probe(connection(company,value,text(value,"password")));}
    public String save(String company,Map<String,Object> input){Map<String,Object> value=validate(company,input);boolean enabled=number(value,"enabled")==1;if(enabled)probe(connection(company,value,text(value,"password")));String encrypted=secrets.encrypt(company,text(value,"password"));String key=text(value,"source_key");if(key.isEmpty())key="PS"+token();require(key.matches("[A-Za-z0-9_-]{1,64}"),"来源标识无效");final String identity=key;
        JdbcTemplate db=repository.db();TransactionTemplate tx=new TransactionTemplate(new DataSourceTransactionManager(db.getDataSource()));
        tx.execute(status->{List<Map<String,Object>> before=db.query("SELECT * FROM oms_order_push_source WHERE company_code=? AND source_key=? FOR UPDATE",ROW,company,identity);if(before.isEmpty()){require(text(input,"source_key").isEmpty()||number(input,"revision")==0,"来源不存在，请刷新");db.update("INSERT INTO oms_order_push_source(company_code,source_key,source_name,host,port,database_name,username,password_cipher,enabled,last_test_status,last_test_time,last_test_message) VALUES (?,?,?,?,?,?,?,?,?,?,IF(?=1,NOW(),NULL),?)",company,identity,value.get("source_name"),value.get("host"),value.get("port"),value.get("database_name"),value.get("username"),encrypted,value.get("enabled"),enabled?"SUCCESS":"UNTESTED",enabled?1:0,enabled?"连接和订单表检查通过":"尚未测试");}
            else{Map<String,Object> old=before.get(0);require(number(old,"revision")==number(input,"revision"),"推送库配置已变化，请刷新后重试");long used=db.queryForObject("SELECT COUNT(*) FROM oms_order_pull_config WHERE company_code=? AND source_key=?",Long.class,company,identity);if(used>0)require(text(old,"host").equals(text(value,"host"))&&number(old,"port")==number(value,"port")&&text(old,"database_name").equals(text(value,"database_name")),"已有店铺引用，修改数据库地址请新增来源并在店铺配置中切换");db.update("UPDATE oms_order_push_source SET source_name=?,host=?,port=?,database_name=?,username=?,password_cipher=?,enabled=?,revision=revision+1,last_test_status=?,last_test_time=IF(?=1,NOW(),NULL),last_test_message=? WHERE company_code=? AND source_key=?",value.get("source_name"),value.get("host"),value.get("port"),value.get("database_name"),value.get("username"),encrypted,value.get("enabled"),enabled?"SUCCESS":"UNTESTED",enabled?1:0,enabled?"连接和订单表检查通过":"尚未测试",company,identity);}return null;});return identity;
    }
    public void testSaved(String company,String key){Map<String,Object> old=row(company,key);try{probe(connection(company,old,secrets.decrypt(company,text(old,"password_cipher"))));repository.db().update("UPDATE oms_order_push_source SET last_test_status='SUCCESS',last_test_time=NOW(),last_test_message='连接和订单表检查通过' WHERE company_code=? AND source_key=? AND revision=?",company,key,old.get("revision"));}catch(IllegalArgumentException e){repository.db().update("UPDATE oms_order_push_source SET last_test_status='FAILED',last_test_time=NOW(),last_test_message=? WHERE company_code=? AND source_key=? AND revision=?",e.getMessage(),company,key,old.get("revision"));throw e;}}
    public void delete(String company,String key){JdbcTemplate db=repository.db();new TransactionTemplate(new DataSourceTransactionManager(db.getDataSource())).execute(status->{db.queryForList("SELECT source_key FROM oms_order_push_source WHERE company_code=? AND source_key=? FOR UPDATE",company,key);require(db.queryForObject("SELECT COUNT(*) FROM oms_order_pull_config WHERE company_code=? AND source_key=?",Long.class,company,key)==0,"推送库已被店铺引用，请先调整店铺配置");require(db.update("DELETE FROM oms_order_push_source WHERE company_code=? AND source_key=?",company,key)==1,"推送库不存在");return null;});}
}
